From aad6348c21855e7cb5a6d13edb5e9bd934ed7f73 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:36:24 +0100
Subject: [PATCH] containments/desktop: badge Folder View panel icon with new
 items

A Folder View widget in a panel gave no sign that a file had arrived in
its folder, such as a finished download. The model now counts the items
added after listing, and the icon shows them as a badge until opened.

BUG: 429304
---
 .../desktop/package/contents/ui/main.qml      |  6 +++
 .../desktop/plugins/folder/foldermodel.cpp    | 48 +++++++++++++++++++
 .../desktop/plugins/folder/foldermodel.h      |  7 +++
 3 files changed, 61 insertions(+)

diff --git a/containments/desktop/package/contents/ui/main.qml b/containments/desktop/package/contents/ui/main.qml
index d3f413b2df..2f3f21b71d 100644
--- a/containments/desktop/package/contents/ui/main.qml
+++ b/containments/desktop/package/contents/ui/main.qml
@@ -100,6 +100,12 @@ ContainmentItem {
     toolTipSubText: ""
     Plasmoid.icon: (!Plasmoid.configuration.useCustomIcon && folderViewLayer.ready) ? symbolicizeIconName(folderViewLayer.view?.model.iconName) : Plasmoid.configuration.icon

+    badgeText: {
+        const newItemCount = (!isContainment && !expanded && folderViewLayer.ready) ? folderViewLayer.view.model.newItemCount : 0;
+        return newItemCount > 0 ? newItemCount.toLocaleString(Qt.locale(), 'f', 0) : "";
+    }
+    onExpandedChanged: folderViewLayer.view?.model.clearNewItems()
+
     onScreenChanged: isUiReady = Plasmoid.containment.corona.isScreenUiReady(root.screen)

     // We want to do this here rather than in the model because we don't always want
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..8a3a35e13f 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -229,10 +229,33 @@ FolderModel::FolderModel(QObject *parent)
     connect(dirLister, &KCoreDirLister::started, this, std::bind(&FolderModel::setStatus, this, Status::Listing));

     QObject::connect(dirLister, &KCoreDirLister::completed, this, [this, dirLister] {
+        m_trackNewItems = true;
         setStatus(Status::Ready);
         Q_EMIT listingCompleted(dirLister->items().urlList());
     });

+    connect(dirLister, &KCoreDirLister::newItems, this, [this](const KFileItemList &items) {
+        if (!m_trackNewItems) {
+            return;
+        }
+        for (const KFileItem &item : items) {
+            m_newItems.insert(item.url());
+        }
+        Q_EMIT newItemCountChanged();
+    });
+    connect(dirLister, &KCoreDirLister::itemsDeleted, this, [this](const KFileItemList &items) {
+        for (const KFileItem &item : items) {
+            m_newItems.remove(item.url());
+        }
+    });
+    connect(dirLister, &KCoreDirLister::refreshItems, this, [this](const QList<QPair<KFileItem, KFileItem>> &items) {
+        for (const auto &[oldItem, newItem] : items) {
+            if (m_newItems.remove(oldItem.url())) {
+                m_newItems.insert(newItem.url());
+            }
+        }
+    });
+
     QObject::connect(dirLister, &KCoreDirLister::canceled, this, [this] {
         setStatus(Status::Canceled);
         Q_EMIT listingCanceled();
@@ -269,6 +292,14 @@ FolderModel::FolderModel(QObject *parent)

     setSourceModel(m_dirModel);

+    for (const auto signal : {&QAbstractItemModel::rowsInserted, &QAbstractItemModel::rowsRemoved}) {
+        connect(this, signal, this, [this] {
+            if (!m_newItems.isEmpty()) {
+                Q_EMIT newItemCountChanged();
+            }
+        });
+    }
+
     connect(this, &QAbstractItemModel::rowsInserted, this, [this](const QModelIndex &parent, int first, int last) {
         for (int i = first; i <= last; ++i) {
             // If screen is not used, we should just clear the positions and return.
@@ -436,6 +467,8 @@ void FolderModel::setUrl(const QString &url)
     beginResetModel();
     m_url = url;
     m_isDirCache.clear();
+    m_trackNewItems = false;
+    clearNewItems();
     m_dirModel->dirLister()->openUrl(resolvedNewUrl);
     clearDragImages();
     m_dragIndexes.clear();
@@ -2281,6 +2314,21 @@ void FolderModel::pasteTo()
     KIO::paste(QApplication::clipboard()->mimeData(), urls.first());
 }

+int FolderModel::newItemCount() const
+{
+    return std::count_if(m_newItems.cbegin(), m_newItems.cend(), [this](const QUrl &url) {
+        return mapFromSource(m_dirModel->indexForUrl(url)).isValid();
+    });
+}
+
+void FolderModel::clearNewItems()
+{
+    if (!m_newItems.isEmpty()) {
+        m_newItems.clear();
+        Q_EMIT newItemCountChanged();
+    }
+}
+
 void FolderModel::refresh()
 {
     m_errorString.clear();
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..f45ca27d9c 100644
