+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -117,6 +117,7 @@ class FolderModel : public QSortFilterProxyModel, public QQmlParserStatus
     Q_PROPERTY(bool showHiddenFiles READ showHiddenFiles WRITE setShowHiddenFiles NOTIFY showHiddenFilesChanged)
     Q_PROPERTY(bool creatingNewItems READ creatingNewItems NOTIFY creatingNewItemsChanged)
     Q_PROPERTY(int selectionCount READ selectionCount NOTIFY selectionCountChanged)
+    Q_PROPERTY(int newItemCount READ newItemCount NOTIFY newItemCountChanged)

 public:
     enum DataRole {
@@ -279,6 +280,9 @@ public:
     Q_INVOKABLE void refresh();
     Q_INVOKABLE void createFolder();

+    int newItemCount() const;
+    Q_INVOKABLE void clearNewItems();
+
     bool screenUsed();

     void setScreen(int screen, SetScreenActions screenActions = SetScreenActions::None);
@@ -324,6 +328,7 @@ Q_SIGNALS:
     void selectionDone();
     void creatingNewItemsChanged() const;
     void selectionCountChanged() const;
+    void newItemCountChanged() const;
     void itemDeleted(const QUrl &url);

 protected:
@@ -415,6 +420,8 @@ private:
     bool m_complete;
     QPoint m_menuPosition;
     bool m_creatingNewItems = false;
+    QSet<QUrl> m_newItems;
+    bool m_trackNewItems = false;
     bool m_unsortedModeOnDrop = false;

     /**
